package com.lexiscan.common; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import org.springframework.web.bind.MethodArgumentNotValidException; import java.time.*; import java.util.*;
@RestControllerAdvice public class GlobalExceptionHandler { record ErrorResponse(Instant timestamp,int status,String error,String message,String path){} @ExceptionHandler(ApiException.class) ResponseEntity<ErrorResponse> api(ApiException e,HttpServletRequest r){return respond(e.status,e.getMessage(),r);} @ExceptionHandler(MethodArgumentNotValidException.class) ResponseEntity<ErrorResponse> validation(MethodArgumentNotValidException e,HttpServletRequest r){return respond(HttpStatus.BAD_REQUEST,e.getBindingResult().getFieldError().getDefaultMessage(),r);} @ExceptionHandler(Exception.class) ResponseEntity<ErrorResponse> other(Exception e,HttpServletRequest r){return respond(HttpStatus.INTERNAL_SERVER_ERROR,"An unexpected error occurred",r);} private ResponseEntity<ErrorResponse> respond(HttpStatus s,String m,HttpServletRequest r){return ResponseEntity.status(s).body(new ErrorResponse(Instant.now(),s.value(),s.getReasonPhrase(),m,r.getRequestURI()));} }
